    const env = validateEnv();
    _unipileClient = new UnipileClient(env.UNIPILE_DSN, env.UNIPILE_ACCESS_TOKEN);
    _unipileConfig = { dsn: env.UNIPILE_DSN };
  }
  return _unipileClient;
}

